(function(root){'use strict';const R=root.Reunion;
function save(s,d,uid){const u=s.people.find(p=>p.id===uid);if(u?.role!=='owner')throw new Error('振込先口座は管理者だけが変更できます。');let b={};for(const k of ['bankName','branchName','accountType','accountNumber','accountHolder']){b[k]=String(d[k]||'').trim();if(b[k].length>100||/[\r\n\x00-\x1f]/.test(b[k]))throw new Error('口座情報は100文字以内・改行なしで入力してください。');}b.accountNumber=b.accountNumber.normalize('NFKC');if(!b.bankName&&!b.branchName&&!b.accountNumber&&!b.accountHolder)b={};else if(!b.bankName||!b.branchName||!b.accountHolder||!['普通','当座'].includes(b.accountType)||!/^\d{7}$/.test(b.accountNumber))throw new Error('銀行名・支店名・種別・名義と7桁の口座番号を入力してください。');if(!String(d.reason||'').trim())throw new Error('変更理由を入力してください。');const before=R.clone(s.settings.bankAccount||{});s.settings.bankAccount=b;R.audit(s,u.name,'振込先口座の設定変更','settings:bank-account',before,b,d.reason);return b;}
root.BankAccount={save};if(typeof module!=='undefined')module.exports=root.BankAccount;
})(typeof globalThis!=='undefined'?globalThis:this);
